                $display("ERROR: a=%0d, b=%0d | Got s=%0d (exp %0d), overflow=%0b (exp %0b)", 
                         $signed(a), $signed(b), $signed(s), $signed(exp_s), overflow, exp_ovf);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Test 1: Zero + Zero
        a = 8'd0; b = 8'd0;
        check(8'd0, 1'b0);

        // Test 2: Positive + Positive (No overflow)
        a = 8'd50; b = 8'd50;
        check(8'd100, 1'b0);

        // Test 3: Positive + Positive (Overflow boundary: 127 + 1)
        a = 8'd127; b = 8'd1;
