        check(8'd0, 1'b0);

        // Test 9: Mixed signs (Negative + Positive -> Never overflows)
        a = 8'h80; b = 8'd1; // -128 + 1 = -127
        check(8'h81, 1'b0);

        // Test 10: Full saturation / alternating test vector sweep (bounded)
        a = 8'h7F; b = 8'h7F; // 127 + 127 = 254 (-2) -> overflow
        check(8'hFE, 1'b1);

        a = 8'h80; b = 8'h80; // -128 + -128 = -256 -> wraps to 0 -> overflow
        check(8'h00, 1'b1);

        // Final Result Evaluation
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
